-- Rentals Phase 46: comparable quotes and recorded landlord approval.
begin;
create table public.rental_maintenance_quotes(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.rental_maintenance_requests(id),organisation_id uuid not null references public.organisations(id),supplier_name text not null check(length(btrim(supplier_name))>0),quote_reference text,amount numeric(14,2) not null check(amount>0),currency_code text not null default 'ZAR' check(currency_code='ZAR'),quote_link text not null,scope_notes text,valid_until date,status text not null default 'submitted' check(status in('submitted','recommended','approved','rejected','expired')),submitted_by uuid not null references auth.users(id),submitted_at timestamptz not null default now(),unique(request_id,supplier_name,quote_reference));
create table public.rental_maintenance_quote_approvals(id uuid primary key default gen_random_uuid(),quote_id uuid not null unique references public.rental_maintenance_quotes(id),request_id uuid not null references public.rental_maintenance_requests(id),organisation_id uuid not null references public.organisations(id),decision text not null check(decision in('approved','rejected')),landlord_name text not null,approval_evidence_link text not null,decision_note text,decided_by uuid not null references auth.users(id),decided_at timestamptz not null default now());
create index rental_maintenance_quotes_request_idx on public.rental_maintenance_quotes(request_id,status,amount);alter table public.rental_maintenance_quotes enable row level security;alter table public.rental_maintenance_quote_approvals enable row level security;revoke all on public.rental_maintenance_quotes,public.rental_maintenance_quote_approvals from anon,authenticated;grant select on public.rental_maintenance_quotes,public.rental_maintenance_quote_approvals to authenticated;
create policy rental_maintenance_quotes_read on public.rental_maintenance_quotes for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_maintenance_quote_approvals_read on public.rental_maintenance_quote_approvals for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_submit_maintenance_quote(p_request uuid,p_supplier text,p_reference text,p_amount numeric,p_link text,p_scope text default null,p_valid_until date default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_maintenance_requests%rowtype;qid uuid;begin if auth.uid() is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or length(btrim(coalesce(p_supplier,'')))=0 or length(btrim(coalesce(p_link,'')))=0 then raise exception 'Supplier, amount and quote evidence are required';end if;select * into r from public.rental_maintenance_requests where id=p_request for update;if not found or not exists(select 1 from public.rental_properties p where p.id=r.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if r.status not in('acknowledged','triaged','assigned') then raise exception 'Request must be triaged before quotes';end if;insert into public.rental_maintenance_quotes(request_id,organisation_id,supplier_name,quote_reference,amount,quote_link,scope_notes,valid_until,submitted_by)values(r.id,r.organisation_id,btrim(p_supplier),nullif(btrim(coalesce(p_reference,'')),''),p_amount,btrim(p_link),nullif(btrim(coalesce(p_scope,'')),''),p_valid_until,auth.uid()) returning id into qid;update public.rental_maintenance_requests set status='triaged' where id=r.id and status='acknowledged';return jsonb_build_object('quote_id',qid,'status','submitted');end$$;
create or replace function public.rental_record_maintenance_quote_decision(p_quote uuid,p_decision text,p_landlord_name text,p_evidence text,p_note text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare q public.rental_maintenance_quotes%rowtype;begin if auth.uid() is null or p_decision not in('approved','rejected') or length(btrim(coalesce(p_landlord_name,'')))=0 or length(btrim(coalesce(p_evidence,'')))=0 then raise exception 'Decision, landlord name and evidence are required';end if;select * into q from public.rental_maintenance_quotes where id=p_quote for update;if not found or not exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=q.request_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if q.status in('approved','rejected') then raise exception 'Quote decision already recorded';end if;insert into public.rental_maintenance_quote_approvals(quote_id,request_id,organisation_id,decision,landlord_name,approval_evidence_link,decision_note,decided_by)values(q.id,q.request_id,q.organisation_id,p_decision,btrim(p_landlord_name),btrim(p_evidence),nullif(btrim(coalesce(p_note,'')),''),auth.uid());update public.rental_maintenance_quotes set status=p_decision where id=q.id;if p_decision='approved' then update public.rental_maintenance_quotes set status='rejected' where request_id=q.request_id and id<>q.id and status in('submitted','recommended');end if;return jsonb_build_object('quote_id',q.id,'status',p_decision);end$$;
revoke execute on function public.rental_submit_maintenance_quote(uuid,text,text,numeric,text,text,date),public.rental_record_maintenance_quote_decision(uuid,text,text,text,text) from public,anon;grant execute on function public.rental_submit_maintenance_quote(uuid,text,text,numeric,text,text,date),public.rental_record_maintenance_quote_decision(uuid,text,text,text,text) to authenticated;commit;
